target=S/'contacts-02-selected-support-guide.png';board.save(target);(S/'contacts-02-guide.json').write_text(json.dumps({'sourceFrames':records,'operation':'Two unchanged complete selected North walk0/walk3 at nearest4x; exact opposite support geometry, no anatomy edits','sha256':sha(target)},indent=2)+'\n')
